#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include "owned_global_flex_binding_plan.h"
#include "disk_model_metadata_cache.h"
#include <iostream>
static void verifySavedFreshFlex(const Graph&original,const OwnedGlobalFlexBindingPlanCandidate&plan,const char*path){
 auto expected=original;for(const auto&b:plan.bindings){auto&values=expected.elements[b.modelElement].attributes[b.destinationAttribute].values;if(b.weightIndex>=values.size())throw std::runtime_error("expected unsupported growth");uint32_t old=wireU32(values[b.weightIndex]);uint32_t incoming=wireU32(expected.elements[b.operatorElement].attributes[b.sourceAttribute].values[0]);float a,c;std::memcpy(&a,&old,4);std::memcpy(&c,&incoming,4);if(floatMutationNeeded(a,c)){incoming=recoveredX87FloatStoreBitsCandidate(incoming);std::memcpy(values[b.weightIndex].wire.data(),&incoming,4);}}
 auto loaded=loadGraph(path);validateGraph(loaded);if(loaded.header!=expected.header||loaded.strings!=expected.strings||loaded.elements.size()!=expected.elements.size())throw std::runtime_error("saved metadata");for(size_t i=0;i<expected.elements.size();++i){const auto&e=expected.elements[i];const auto&l=loaded.elements[i];if(e.id!=l.id||e.type!=l.type||e.name!=l.name||e.attributes.size()!=l.attributes.size())throw std::runtime_error("saved element");for(size_t j=0;j<e.attributes.size();++j){const auto&a=e.attributes[j];const auto&b=l.attributes[j];if(a.name!=b.name||a.type!=b.type||a.values.size()!=b.values.size())throw std::runtime_error("saved attribute");for(size_t k=0;k<a.values.size();++k){const auto&v=a.values[k];const auto&w=b.values[k];if(v.wire!=w.wire||v.text!=w.text||v.reference!=w.reference||v.stringIndex!=w.stringIndex)throw std::runtime_error("saved payload");}}}std::cout<<"fresh_flex_cli_complete_saved_graph=passed\n";
}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3&&argc!=4)throw std::runtime_error("session and explicit content root, optional saved CLI graph required");auto original=loadGraph(argv[1]);RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(original,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external input");});DiskModelMetadataCacheCandidate cache;RecoveredGlobalFlexRegistryCandidate registry;std::vector<uint16_t>handles;auto root=std::filesystem::weakly_canonical(argv[2]);
 auto plan=discoverOwnedGlobalFlexBindingsCandidate(p,registry,[&](uint32_t model)->std::vector<MdlFlexControllerMetadata>*{const auto&e=p.graph.elements[model];for(const auto&a:e.attributes)if(p.graph.strings.at(a.name)=="modelName"&&a.type==5&&a.values.size()==1){std::filesystem::path relative=a.values[0].text;if(relative.is_absolute())throw std::runtime_error("absolute model path");for(const auto&part:relative)if(part=="..")throw std::runtime_error("model traversal");auto path=std::filesystem::weakly_canonical(root/relative);auto inside=path.lexically_relative(root);if(inside.empty()||*inside.begin()=="..")throw std::runtime_error("model outside root");auto h=cache.acquire(path);if(h!=0xffff)handles.push_back(h);return cache.controllers(h);}return nullptr;});
 if(plan.bindings.empty()||plan.missingMetadata||plan.missingController)throw std::runtime_error("incomplete fixture binding discovery");size_t writes=0,noops=0,rejected=0;
 for(const auto&b:plan.bindings){auto source=p.graph.elements[b.operatorElement].attributes[b.sourceAttribute].values[0];auto&values=p.graph.elements[b.modelElement].attributes[b.destinationAttribute].values;if(b.weightIndex>=values.size()){auto r=executeOwnedGlobalFlexCandidate(p,b,0);if(r.changed)throw std::runtime_error("out-of-range accepted");++rejected;continue;}uint32_t old=wireU32(values[b.weightIndex]);uint32_t incoming=wireU32(source);float oldFloat,newFloat;std::memcpy(&oldFloat,&old,4);std::memcpy(&newFloat,&incoming,4);bool expected=floatMutationNeeded(oldFloat,newFloat);auto r=executeOwnedGlobalFlexCandidate(p,b,0);if(r.dispatch!=RecoveredFlexExecuteDispatchCandidate::Array||r.changed!=expected)throw std::runtime_error("planned execution result");if(expected){if(wireU32(values[b.weightIndex])!=recoveredX87FloatStoreBitsCandidate(incoming))throw std::runtime_error("weight payload");++writes;}else ++noops;}
 if(rejected!=plan.outOfRange)throw std::runtime_error("out-of-range accounting");if(argc==4)verifySavedFreshFlex(original,plan,argv[3]);for(auto h:handles)cache.release(h);p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(p.scene.size()||p.scene.references.nodes.allocationCount())throw std::runtime_error("teardown");std::cout<<"fresh_registry_bindings="<<plan.bindings.size()<<" registry_names="<<registry.names().size()<<" writes="<<writes<<" equal="<<noops<<" requires_weight_growth="<<rejected<<" metadata_missing="<<plan.missingMetadata<<" controller_missing="<<plan.missingController<<" native_historical_mapping=unverified caller_order=serialized\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
